window.__audit = function(){
function parse(c){const m=c.match(/rgba?\(([^)]+)\)/);if(!m){const o=c.match(/oklch|color\(/);return null;}const p=m[1].split(/[ ,\/]+/).filter(Boolean).map(Number);return {r:p[0],g:p[1],b:p[2],a:p.length>3?p[3]:1};}
function L(c){const f=v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)};return 0.2126*f(c.r)+0.7152*f(c.g)+0.0722*f(c.b);}
function blend(top,bot){const a=top.a;return {r:top.r*a+bot.r*(1-a),g:top.g*a+bot.g*(1-a),b:top.b*a+bot.b*(1-a),a:1};}
function effBg(el){const stack=[];let e=el;while(e&&e.nodeType===1){const c=parse(getComputedStyle(e).backgroundColor);if(c&&c.a>0)stack.push(c);if(c&&c.a>=1)break;e=e.parentElement;}let base={r:31,g:21,b:14,a:1};for(let i=stack.length-1;i>=0;i--)base=blend(stack[i],base);return base;}
function opac(el){let o=1,e=el;while(e&&e.nodeType===1){o*=parseFloat(getComputedStyle(e).opacity);e=e.parentElement;}return o;}
const rows=[];const sizes={};
const tw=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;
const seen=new Set();
while(n=tw.nextNode()){const t=n.textContent.trim();if(!t)continue;const el=n.parentElement;if(seen.has(el))continue;seen.add(el);if(el.closest('.impeccable-overlay,script,style'))continue;const cs=getComputedStyle(el);const r=el.getBoundingClientRect();if(r.width===0||cs.visibility==='hidden'||cs.display==='none')continue;
let fg=parse(cs.color);if(!fg){rows.push({t:t.slice(0,40),color:cs.color,note:'unparsed'});continue;}
const bg=effBg(el);const o=opac(el);let f={...fg,a:fg.a*o};const fgB=blend(f,bg);
const A=L(fgB),B=L(bg);const ratio=(Math.max(A,B)+0.05)/(Math.min(A,B)+0.05);
const fs=parseFloat(cs.fontSize);sizes[fs]=(sizes[fs]||0)+1;
rows.push({t:t.slice(0,40),fs,fw:cs.fontWeight,ff:cs.fontFamily.split(',')[0],color:cs.color,opacity:+o.toFixed(2),ratio:+ratio.toFixed(2),cls:(el.getAttribute('class')||'').slice(0,90)});}
return {sizes,rows};
};
const r=__audit(); const low=r.rows.filter(x=>x.ratio!==undefined&&x.ratio<4.5).sort((a,b)=>a.ratio-b.ratio); ({sizeCounts:r.sizes,totalTextEls:r.rows.length, below4_5:low.length, low:low.slice(0,40), unparsed:r.rows.filter(x=>x.note)})

